from django.db import migrations, models
from django.utils.html import escape


def convert_body_to_html(apps, schema_editor):
    """Тексты постов до этой миграции - обычный текст (рендерился через linebreaksbr).
    Теперь body - HTML из мини-редактора (см. admin-richtext.js), рендерится как |safe.
    Экранируем спецсимволы старых записей и превращаем переносы строк в теги, чтобы
    уже созданные посты не потеряли форматирование."""
    WeeklyPost = apps.get_model('library', 'WeeklyPost')
    for post in WeeklyPost.objects.all():
        if '<' in post.body:
            continue
        paragraphs = post.body.split('\n\n')
        html = ''.join(f'<p>{escape(p).replace(chr(10), "<br>")}</p>' for p in paragraphs if p.strip())
        post.body = html
        post.save(update_fields=['body'])


